"""install_tool.py — 注册 MCP 风格工具到工具注册表。

工具脚本规范（与 tools/shell_mcp.py 一致）：
- TOOL_SCHEMA: OpenAI function 格式列表
- call_tool(method, params): 统一分发入口
- health_check(): 返回 bool

用法：
  install_tool.py <script.py> --name <工具名> [--description ...] [--category ...]
  install_tool.py --list
  install_tool.py --remove <工具名>

脚本会被复制到 {RUNTIME_HOME}/tools/<name>.py 后注册，
避免引用临时路径。仅使用 Python3 标准库。
"""
import argparse
import importlib.util
import shutil
import sys
from pathlib import Path

BASE_DIR = Path(__file__).resolve().parent.parent       # agent_runtime/
sys.path.insert(0, str(BASE_DIR.parent))                # backend/

from agent_runtime.core.config import RuntimeConfig      # noqa: E402
from agent_runtime.tools.mcp_client import ToolRegistry  # noqa: E402


def _validate_script(path):
    """校验脚本符合工具规范（可加载且有 TOOL_SCHEMA）。"""
    try:
        spec = importlib.util.spec_from_file_location('tool_check', str(path))
        mod = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)
    except Exception as e:  # noqa: BLE001
        print('错误: 脚本加载失败: %s' % e)
        return False
    if not hasattr(mod, 'TOOL_SCHEMA'):
        print('错误: 脚本缺少 TOOL_SCHEMA（OpenAI function 格式列表）')
        return False
    if not hasattr(mod, 'call_tool'):
        print('警告: 脚本缺少 call_tool(method, params) 分发入口')
    return True


def main():
    parser = argparse.ArgumentParser(description='注册 MCP 工具')
    parser.add_argument('script', nargs='?', help='工具脚本路径（.py）')
    parser.add_argument('--name', help='工具名（snake_case）')
    parser.add_argument('--description', default='', help='工具描述')
    parser.add_argument('--category', default='general', help='工具分类')
    parser.add_argument('--list', action='store_true', help='列出已注册工具')
    parser.add_argument('--remove', metavar='NAME', help='注销指定工具')
    args = parser.parse_args()

    config = RuntimeConfig(agent_id='cli')
    config.ensure_dirs()
    registry = ToolRegistry(config)

    if args.list:
        for t in registry.list_tools():
            print('%-12s [%s] %s — methods: %s' % (
                t['name'], t['category'], t['description'],
                ','.join(t['methods']) or '-'))
        return 0

    if args.remove:
        if registry.unregister(args.remove):
            print('工具 %s 已注销' % args.remove)
            return 0
        print('错误: 工具 %s 未注册' % args.remove)
        return 1

    if not args.script or not args.name:
        parser.print_help()
        return 1
    src = Path(args.script).resolve()
    if not src.exists():
        print('错误: 脚本不存在: %s' % src)
        return 1
    if not _validate_script(src):
        return 1

    # 复制到员工运行时目录后注册（避免引用临时路径）
    tool_dir = Path(config.runtime_home) / 'tools'
    tool_dir.mkdir(parents=True, exist_ok=True)
    dest = tool_dir / ('%s.py' % args.name)
    shutil.copyfile(src, dest)
    if registry.register(args.name, dest, description=args.description,
                         category=args.category):
        print('工具 %s 已注册（%s）' % (args.name, dest))
        return 0
    return 1


if __name__ == '__main__':
    sys.exit(main())
